insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-subjects-before-remint-sam-2026-11-22','decision','Finish common subjects and local subject titles before re-minting M-IDs','Sam, 2026-11-22 (S707): "I''m thinking it would be best to finish the common subject and local subject titles before reminting MIDs." Then: "order sounds good. i do need to define finish--you can help me establish when we have a sufficient collected and curated dataset to work with for the needed or prioritized remints"',array['commons','subjects','m-id','remint'],'verified','Sam in session, 2026-11-22 (S707)','Sam',now(),'SkyPrion (S707)','2026-11-22'),
('f-aed-electricity-gave-elec-m90-s707','fact','The subject map''s AED: Electricity put an ELEC prefix on 45 M-IDs shared across colleges','S707: only Cerritos uses AED (Adult Education). As the modal subject it gave ELEC M90xx and others their prefix: High School English, Spanish, US History, GED prep, Fitness for Older Adults, Vocational ESL; about 15 are electrical. 45 of 46 such M-IDs hold other colleges'' courses. AED is unmapped (S707 PR); the re-mint waits on the readiness gate.',array['commons','subjects','m-id','remint'],'proposed','kb/coci_minted_memberships.json read 2026-11-22',null,null,'SkyPrion (S707)','2026-11-22'),
('d-remint-order-subjects-outcomes-dryrun-s707','decision','Re-mint order: settle the scope''s codes, rerun the outcomes compare, then one dry run','S707, on Sam''s call: settle subject codes for the M-IDs in a re-mint''s scope (AED first), not every college; rerun kb/_mid_outcomes_compare.py (course_outcomes now 45,270 rows at 35 colleges, against 17,349 at 18 on 11-12); then one dry run, prefix from settled codes, clusters checked by outcomes. SLOs never decide alone. Sam approved the order.',array['commons','subjects','m-id','remint'],'proposed','Sam in session, S707',null,null,'SkyPrion (S707)','2026-11-22'),
('d-remint-ready-gate-draft-s707','decision','Draft: when an M-ID is ready to re-mint','S707 draft, Sam''s to set: an M-ID is ready when every member''s code (and noncredit category) has a settled common code, by a person, a filing, or a statewide default for that code; members agree on one code or split along it; outcomes compared on the current table, strong or partial splits answered. A scope runs its ready M-IDs and holds the rest by name.',array['commons','subjects','m-id','remint'],'proposed','S707 session',null,null,'SkyPrion (S707)','2026-11-22')
on conflict (slug) do nothing;
